from vlb_traj import Session
import numpy as np

def info(tag):
 st=s.state(); print(tag,'tcp',np.round(st['robot']['tcp_position'],3),'food',np.round(st['entities']['cooked_food']['position'],3),'door',np.round(st['entities']['microwave_seen']['joint_positions'],3),'success',s.status()['success'])
def pose(p,q,grip,n=20,tol=.08):
 ik=s.ik(p,q); print('IK',np.round(p,3),ik['success'])
 if not ik['success']: return False
 a=np.r_[ik['joint_positions'],grip]
 for _ in range(n): s.step(a)
 st=s.state(); err=np.linalg.norm(np.array(st['robot']['tcp_position'])-p)
 info('POSE %.3f'%err)
 return err<tol
with Session() as s:
 s.record_start()
 s.skill('pick',target_entity_name='microwave_seen'); s.skill('open_door',target_container_name='microwave_seen'); s.skill('open_gripper')
 qd=np.array(s.state()['robot']['tcp_quaternion_wxyz'])
 for p in [[-.4528,-.2329,1.391],[0,0,1.42],[.15,-.05,1.38],[.25,-.05,1.30]]: pose(p,qd,[.04,.04],12)
 r=s.skill('pick',target_entity_name='cooked_food'); print('PICK',r['stage_success']); info('GRASP')
 if r['stage_success']:
  for p in [[.25,-.04,1.30],[.15,.02,1.35],[.05,.10,1.35],[0,.10,1.40]]:
   if not pose(p,qd,[0,0],20): break
  else:
   q0=qd/np.linalg.norm(qd); qi=np.array([1.,0,0,0]);
   if np.dot(q0,qi)<0:qi=-qi
   good=True
   for t in np.linspace(.08,1,12):
    q=(1-t)*q0+t*qi; q/=np.linalg.norm(q)
    if not pose([0,.10,1.40],q,[0,0],18,.08): good=False; print('ROTFAIL',t); break
   if good:
    for p in [[-.05,.16,1.48],[-.15,.22,1.48],[-.15,.32,1.48],[-.15,.32,1.35],[-.15,.32,1.20],[-.15,.32,1.05],[-.15,.32,.92],[-.15,.32,.82]]:
     if not pose(p,qi,[0,0],24,.08): print('DESCENTFAIL',p); good=False; break
   if good:
    info('PRE_RELEASE'); print('RELEASE',s.skill('open_gripper')); info('RELEASED')
    print('CLOSE',s.skill('close_door',target_container_name='microwave_seen')); info('CLOSED')
    print('PRESS',s.skill('press',target_pos=[.10814,.20012,.917],target_quat=qi,move_vector=[0,-.04,0],max_n_substep=1)); info('PRESSED')
 print('FINAL',s.status())
 a=s.record_stop(); print('N',len(a)); s.save_trajectory(a,'/app/output/trajectory.npz')
